import{z as l,x as s,o as t,c as p,q as B,j as o,D as e,d as a,s as A,S as i,b as n}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"算法选型的工程视角","description":"","frontmatter":{"title":"算法选型的工程视角","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ae-selection-engineering.md","filePath":"cs/ae-selection-engineering.md","lastUpdated":1791413859000}'),d={name:"cs/ae-selection-engineering.md"};function g(c,E,m,D,_,f){const r=s("Mermaid");return t(),p("div",null,[E[2]||(E[2]=B('<h1 id="算法选型的工程视角" tabindex="-1">算法选型的工程视角 <a class="header-anchor" href="#算法选型的工程视角" aria-label="Permalink to &quot;算法选型的工程视角&quot;">​</a></h1><div class="epigraph"><p>渐近记号回答「最终谁赢」，工程选型回答「在这台机器、这批数据、这个交付日期下谁赢」；两个问题都值得问，但只有后者会被部署。</p><footer>—— 据 Knuth, Structured Programming with go to Statements, 1974；Bentley, Writing Efficient Programs, 1982 整理</footer></div><p><a href="/cs/pe3-map">上一课</a>给「性能工程案例」收束：定需求、搭测量、查回归、算容量、追长尾、对成本七课拼成一个周期，三条骨架跨场景成立——一切主张带判据、测量的是三元组、预算同构，Amdahl 封收益上限、Little 配在途资源。性能的纪律在前收束；更早，主干课把「图、代数与近似算法」收在 <a href="/cs/word-ram">word RAM</a> 上：一旦承认机器字有 \\(w\\) 比特宽，比较模型的下界就被字级并行撬动。这个收束正是本课程的入口——主干课给了渐近记号、模型与证明，本课程「算法工程实践」把镜头掉转：在真实的规模、分布、硬件与交付约束下，算法如何被选中、调快、验证与交付。本课是第一课，先立一个全课共用的四问框架；后面七课都默认你已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>教科书按渐近阶给答案，但渐近陈述只对 \\(n\\to\\infty\\) 成立，而常数、输入分布、内存预算与现成实现在有限规模上共同决定赢家。缺口不是再学一个更优的算法，而是一套把约束摆上桌的选型流程。不这么做会错在两头：在 \\(n=10^3\\) 的小表上搬出渐近最优的斐波那契堆，维护了指针与摊还边界，却输给一个数组的线性扫描；反过来，在 \\(10^9\\) 规模上沿用为小区间调好的插入排序，常数再省也追不上阶的差距。第三类错误更隐蔽：分布搞错——几乎有序的真实数据上，自适应排序远胜「渐近更优」的非自适应实现，题目其实换了。</p><p><span class="marginnote">术语翻译：自适应排序就是用「输入里已经有多少有序」来省比较的排序——\\(O(n\\log r)\\) 里的 \\(r\\) 是乱序程度；数据完全有序时 \\(r=1\\)，一趟 \\(O(n)\\) 扫描就收工，而普通快排照样老老实实比满 \\(O(n\\log n)\\) 次。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选型四问，按序回答：</p><p>第一问，<strong>规模与分布</strong>。\\(n\\) 的量级决定渐近是否已经压倒常数；两条实现的时间曲线 \\(c_1 f(n)\\) 与 \\(c_2 g(n)\\) 的交叉点由 \\(c_1 f(n)=c_2 g(n)\\) 解出，交叉点之前选简单的那个。键的分布决定算法族：比较排序、基数排序、哈希与搜索树在不同分布下换位。</p><p>第二问，<strong>资源预算</strong>。内存上限、缓存大小、可并行度；同一算法在内存与外存里是两道题，在 L2 与 DRAM 屋顶下也是两个点。</p><p>第三问，<strong>现成实现</strong>。标准库与成熟库里有没有、接口能不能套上（比较器、分配器、错误语义）。自写是显式决定：维护与出错成本计入选型。</p><p>第四问，<strong>变化方向</strong>。规模会不会涨一个量级、分布会不会漂、会不会换硬件；为今天的 \\(n\\) 选交叉点之下的简单算法时，留一条量级涨了就换的退路。</p>',12)),(t(),o(i,null,{default:e(()=>[A(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%97%AE%E9%A2%98%E4%B8%8E%E8%AF%AD%E4%B9%89%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20SIZE%5B%22%E8%A7%84%E6%A8%A1%E4%B8%8E%E5%88%86%E5%B8%83%EF%BC%9An%20%E7%9A%84%E9%87%8F%E7%BA%A7%E3%80%81%E9%94%AE%E7%9A%84%E5%BD%A2%E7%8A%B6%22%5D%0A%20%20SIZE%20--%3E%20RES%5B%22%E8%B5%84%E6%BA%90%E9%A2%84%E7%AE%97%EF%BC%9A%E5%86%85%E5%AD%98%E3%80%81%E7%BC%93%E5%AD%98%E3%80%81%E5%B9%B6%E8%A1%8C%E5%BA%A6%22%5D%0A%20%20RES%20--%3E%20CAND%5B%22%E5%80%99%E9%80%89%E9%9B%86%EF%BC%9A%E5%BA%93%E9%87%8C%E7%9A%84%E4%B8%8E%E8%87%AA%E5%86%99%E7%9A%84%22%5D%0A%20%20CAND%20--%3E%20MEAS%5B%22%E6%8C%89%E5%90%8C%E4%B8%80%E8%BE%93%E5%85%A5%E5%88%86%E5%B8%83%E6%B5%8B%E9%87%8F%22%5D%0A%20%20MEAS%20--%3E%20PICK%5B%22%E9%87%87%E7%94%A8%EF%BC%8C%E5%B9%B6%E5%86%99%E4%B8%8B%E9%87%8D%E9%80%89%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20PICK%20--%3E%20REVISIT%5B%22%E8%A7%84%E6%A8%A1%E6%88%96%E5%88%86%E5%B8%83%E5%8F%98%E5%8C%96%E6%97%B6%E5%9B%9E%E5%88%B0%E7%AC%AC%E4%B8%80%E9%97%AE%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=n("h2",{id:"机制",tabindex:"-1"},[a("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=n("p",null,"为什么渐近终究获胜：常数是乘性的，两条曲线之比 \\(\\dfrac{c_2 g(n)}{c_1 f(n)}\\) 在阶差存在时随 \\(n\\) 发散，但发散可以很慢。取 \\(f(n)=n\\log n\\)、\\(g(n)=n^2\\)、\\(c_2/c_1=1000\\)，交叉点在 \\(n/\\log_2 n=1000\\) 附近，即 \\(n\\) 约两万；也就是说，一万多条记录以内，「平方」实现完全可能赢，阈值要靠测，不靠感觉。",-1)),E[5]||(E[5]=n("p",null,[a("为什么分布能换掉答案：几乎有序输入上的自适应排序，比较次数降到 \\(O(n\\log r)\\)（\\(r\\) 为乱序程度），直接砍到接近线性。数据库优化器是把选型制度化的最大现场：join 不写死一种算法，而是按统计信息在候选间挑，"),n("a",{href:"/cs/sort-merge-join"},"排序归并连接"),a("只是其中被挑中的一支。为什么维护算进机制：库函数一行、有测试与文档，自写结构省下的每毫秒都要乘上未来改动的风险——这正是 Knuth「过早优化是万恶之源」在选型层面的含义。")],-1)),E[6]||(E[6]=n("p",null,[n("span",{class:"marginnote"},"交叉点被主流实现写进了代码：libstdc++ 的 std::sort 在子区间低于阈值 _S_threshold = 16 时切插入排序，pdqsort 取 24。教科书里「渐近更优」的选择，在工程里被一个两位数的小区间常数否决。")],-1)),E[7]||(E[7]=n("p",null,"方法一节的图回答「选型四问按什么顺序问」，下面这张回答另一个问题：两条实现的时间曲线交叉时，交叉点两侧各自怎么选。",-1)),(t(),o(i,null,{default:e(()=>[A(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%AE%9E%E7%8E%B0%E4%B8%80%3A%20c1%20n%20log%20n%20(%E9%98%B6%E4%BD%8E%E4%BD%86%E5%B8%B8%E6%95%B0%E5%A4%A7)%22%5D%20--%3E%20X%7B%22%E5%BD%93%E5%89%8D%20n%20%E5%9C%A8%E4%BA%A4%E5%8F%89%E7%82%B9%E5%93%AA%E4%BE%A7%3F%22%7D%0A%20%20B%5B%22%E5%AE%9E%E7%8E%B0%E4%BA%8C%3A%20c2%20n%5E2%20(%E9%98%B6%E9%AB%98%E4%BD%86%E5%B8%B8%E6%95%B0%E5%B0%8F)%22%5D%20--%3E%20X%0A%20%20X%20--%20%22n%20%E4%BD%8E%E4%BA%8E%E4%BA%A4%E5%8F%89%E7%82%B9%22%20--%3E%20W2%5B%22%E5%B9%B3%E6%96%B9%E5%AE%9E%E7%8E%B0%E5%8F%AF%E8%83%BD%E5%AE%9E%E6%B5%8B%E6%9B%B4%E5%BF%AB%3A%20%E5%85%88%E7%94%A8%E7%AE%80%E5%8D%95%E7%9A%84%22%5D%0A%20%20X%20--%20%22n%20%E9%AB%98%E4%BA%8E%E4%BA%A4%E5%8F%89%E7%82%B9%22%20--%3E%20W1%5B%22n%20log%20n%20%E5%BF%85%E8%83%9C%2C%20%E5%B7%AE%E8%B7%9D%E9%9A%8F%20n%20%E6%8B%89%E5%BC%80%22%5D%0A%20%20W2%20--%3E%20P%5B%22%E5%86%99%E4%B8%8B%E9%87%8D%E9%80%89%E6%9D%A1%E4%BB%B6%3A%20n%20%E6%B6%A8%E8%BF%87%E9%98%88%E5%80%BC%E5%8D%B3%E6%8D%A2%22%5D%0A%20%20W1%20--%3E%20P%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[8]||(E[8]=B('<p><span class="marginnote">数字实例：解交叉点 \\(c_1\\,n\\log_2 n = c_2\\,n^2\\)、\\(\\frac{c_2}{c_1}=\\frac{1}{1000}\\)，即 \\(n/\\log_2 n = 1000\\)——试 \\(n=14000\\)，\\(\\log_2 14000\\approx 13.8\\)，\\(14000/13.8\\approx 1014\\)，恰好过线。也就是说一万多条记录以内，「平方」实现完全可能更快，这条线要靠基准扫出来。</span></p><p><span class="marginnote">常见误区：初学者容易把「渐近更优」当成「永远更好」，也容易把「今天实测更快」当成「永远更快」——两个方向都是同一个错：忘了结论只在交叉点的一侧成立。写选型结论时把阈值和重选条件一起写下来，就是给未来的自己留退路。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只立框架，不落入单点优化：压常数、缓存布局、字内并行分属接下来三课。渐近记号本身的定义与性质见<a href="/cs/asymptotic-notation">渐近记号</a>，本课不再推。选型结论有保质期：规模涨一个量级、分布漂移、硬件换代，任一触发都回到第一问；「怎么测才作数」是基准一课的纪律。并行与外存各有专课，本课程不重讲。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>选型四问按序回答：规模与分布、资源预算、现成实现、变化方向；渐近只在第四问之后登场。</li><li>交叉点之前常数说了算：\\(c_2/c_1=1000\\) 时 \\(n\\log n\\) 与 \\(n^2\\) 的交叉点在一两万条记录量级。</li><li>分布改变题目：自适应实现在真实数据上常击败「渐近更优」的选择，join 由优化器按统计选。</li><li>库是默认答案，自写是显式决定；维护与错误成本计入选型。</li><li>选型结论有保质期：规模、分布、硬件变化即重选，判定靠基准课的测量纪律。</li><li>出处：Knuth, <em>Structured Programming with go to Statements</em>, 1974；Bentley, <em>Writing Efficient Programs</em>, 1982；据本课四问口径整理。</li></ul>',6))])}const C=l(d,[["render",g]]);export{u as __pageData,C as default};
